mapper.select:
SELECT r.*, 
FROM SF_REPORT r
WHERE r.REPORT_ID = #{reportId}

mapper.update:
UPDATE SF_REPORT
SET STATUS = 'REJECTED',
    REJECT_REASON = #{reason}
WHERE REPORT_ID = #{reportId}
  AND INCIDENT_ID IS NULL
  AND STATUS IN ('RECEIVED', 'REVIEWING')

mapper.select:
SELECT PHOTO_URL FROM SF_REPORT_PHOTO
WHERE REPORT_ID = #{reportId}
ORDER BY SORT_ORDER
